import{_ as o,o as t,c as i,a2 as n}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"ADR-0008 — Endpoint pubblico GET /client-config per il bootstrap del client","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0008-client-config-endpoint.md","filePath":"adr/0008-client-config-endpoint.md"}'),a={name:"adr/0008-client-config-endpoint.md"};function r(l,e,c,d,s,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0008-—-endpoint-pubblico-get-client-config-per-il-bootstrap-del-client" tabindex="-1">ADR-0008 — Endpoint pubblico <code>GET /client-config</code> per il bootstrap del client <a class="header-anchor" href="#adr-0008-—-endpoint-pubblico-get-client-config-per-il-bootstrap-del-client" aria-label="Permalink to &quot;ADR-0008 — Endpoint pubblico `GET /client-config` per il bootstrap del client&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (spec §3.5.1 aggiornato)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-23</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§1.3 (flusso di login), §3.3.1 (client Keycloak), §2.6.6 (elenco server nel Config Profile)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no (dopo l aggiornamento di §3.5.1)</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Per avviare il login PKCE il client desktop deve conoscere l&#39;issuer OIDC (URL del realm Keycloak) e il <code>client_id</code> <code>memobrain-desktop</code>, oltre all&#39;endpoint gRPC delle notifiche. Lo spec prevede che il Config Profile contenga un &quot;elenco server/URL&quot;, ma la config effettiva è disponibile solo <strong>dopo</strong> il login. Chiedere all&#39;utente di inserire a mano issuer e client id è fragile.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p>Il cloud espone <code>GET /api/v1/client-config</code> <strong>senza autenticazione</strong> con <code>{issuer, desktop_client_id, audience, grpc_endpoint, api_version}</code>. L&#39;utente inserisce solo l&#39;URL del server; il client scarica il documento, esegue la discovery OIDC sull&#39;issuer e avvia il login. I valori provengono dalla configurazione del servizio (<code>OIDC_ISSUER</code>, <code>OIDC_DESKTOP_CLIENT_ID</code>, <code>OIDC_AUDIENCE</code>, <code>PUBLIC_GRPC_ADDR</code>). Nessuna informazione sensibile: issuer e client id pubblico sono già osservabili nel flusso del browser.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Issuer e client id nelle impostazioni del client</strong> — scartata: errori di configurazione frequenti, nessuna rotazione centralizzata.</li><li><strong>Documento statico <code>/.well-known/memobrain</code></strong> — equivalente; si è preferito restare sotto <code>/api/v1</code> per versionamento e contratto OpenAPI.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><p>Endpoint implementato (<code>services/cloud/internal/system</code>) e coperto dai test di integrazione; la riga corrispondente è stata aggiunta a <code>Specifications.md</code> §3.5.1 su richiesta dell&#39;owner.</p>',10)])])}const f=o(a,[["render",r]]);export{u as __pageData,f as default};
